def longest_unique_substring(s: str) -> int:
    if not s:
        return 0

    left = cur_len = best = 0
    seen = set()

    for right, char in enumerate(s):
        while char in seen and left < right:
            seen.remove(s[left])
            left += 1

        seen.add(char)
        cur_len = right - left + 1
        if cur_len > best:
            best = cur_len

    return best

from collections import deque

def shortest_path(grid: list[list[int]]) -> int:
    if not grid or not grid[0]: return -1  # empty grid
    rows, cols = len(grid), len(grid[0])
    start = (0, 0)
    goal = (rows - 1, cols - 1)

    if grid[start[0]][start[1]] == 1 or grid[goal[0]][goal[1]] == 1: return -1
    if start == goal and grid[start[0]][start[1]] == 0: return 0

    q = deque([(start, 0)])
    seen = {start}

    while q:
        (r, c), dist = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in seen:
                    if (nr, nc) == goal: return dist + 1
                    seen.add((nr, nc))
                    q.append(((nr, nc), dist + 1))

    return -1

from bisect import bisect_left

def lis_length(nums: list[int]) -> int:
    if not nums:
        return 0

    tails = [nums[0]]

    for x in nums[1:]:
        # Find position where we can extend or replace
        pos = bisect_left(tails, x)

        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = min(tails[pos], x)  # redundant but explicit

    return len(tails)

from collections import deque

def is_bipartite(n: int, edges: list[tuple[int, int]]) -> bool:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        if not (0 <= u < n and 0 <= v < n):
            return False
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n
    visited = [False] * n

    for start_node in range(n):
        if not adj[start_node]:
            continue
        q = deque([start_node])
        color[start_node] = 0
        visited[start_node] = True
        while q:
            node = q.popleft()
            current_color = color[node]
            next_color = 1 - current_color
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    color[neighbor] = next_color
                    q.append(neighbor)
                elif color[neighbor] == current_color:
                    return False

    return True

from collections import deque

class RingBuffer:
    def __init__(self, capacity: int):
        self.capacity = max(0, capacity)
        self.buffer = deque()
        if self.capacity == 0:
            self._empty_flag = True
        else:
            self._empty_flag = False

    def write(self, val: any) -> None:
        if not self.capacity or self._empty_flag:
            return
        if len(self.buffer) >= self.capacity:
            self.buffer.popleft()
        self.buffer.append(val)
        self._empty_flag = False

    def read_all(self) -> list:
        if self._empty_flag:
            return []
        # Snapshot current contents without consuming; deque is safe here.
        result = list(self.buffer)
        return result
